const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

window.__sleep = (ms) => new Promise(r => setTimeout(r, ms));
window.__lead = () => { const s = window.__ensemble.getState(); const c = s.chats.find(c => c.id === s.chatId); return (c && c.leadId) || s.settings.leadId || s.accounts.find(a => a.enabled).id; };
// Shows the hover actions of the latest message of each kind, as a pointer resting on it would.
window.__hover = () => {
  const u = [...document.querySelectorAll('.group\\/u')].pop();
  const a = [...document.querySelectorAll('.group\\/a')].pop();
  for (const g of [u, a]) { const d = g && g.querySelector(':scope > .pointer-events-none'); if (d) d.style.opacity = '1'; }
  return !!u + '/' + !!a;
};
window.__palette = async (q) => {
  window.__ensemble.getState().setModal({ kind: 'palette' });
  await window.__sleep(300);
  const el = document.querySelector('[cmdk-input]');
  if (el) { Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(el, q); el.dispatchEvent(new Event('input', { bubbles: true })); }
  await window.__sleep(500);
  return [...document.querySelectorAll('[cmdk-group-heading]')].map(h => h.textContent).join(' > ') + ' | first: ' + (document.querySelector('[cmdk-item]')?.textContent || '').slice(0, 40);
};
return 'helpers';
